      "keystrokes": "python3 - << 'EOF'
import re, zlib
data = open('/app/Harmony.pdf','rb').read()
# find obj 16 stream
for num in [5,13,16,8]:
    m = re.search(rb'(?<!\d)'+str(num).encode()+rb' 0 obj\n<<\n/Length (\d+)\n/Filter /FlateDecode\n>>\nstream\n(.*?endstream)\nendobj', data, re.S)
    if m:
        length = int(m.group(1))
        raw = m.group(2)  # raw until endstream (includes trailing newline before endstream)
        print('obj', num, 'length field:', length, 'actual raw bytes:', len(raw))
        try:
            dec = zlib.decompress(raw)
            print('  decompressed bytes:', len(dec))
            print('  content:', repr(dec[:600]))
            print('---')
EOF
